// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count total Friday the 13ths in a full 400-year cycle.

// Earliest Friday the 13th
var date = new DateTime(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");

// Count in a 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var start = new DateTime(1, 1, 1);
var end = start.AddYears(400);

for (var d = new DateTime(1, 1, 13); d < end; d = d.AddMonths(1))
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
EOF
